const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.doctofam.com/api/appointments',
  qs: {
    clinicId: 'SOME_STRING_VALUE',
    patientId: 'SOME_STRING_VALUE',
    startTime: 'SOME_STRING_VALUE',
    endTime: 'SOME_STRING_VALUE',
    fields: 'SOME_STRING_VALUE'
  },
  headers: {Authorization: 'Basic REPLACE_BASIC_AUTH'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

